import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def latent_vectors(ctx):
    latent = torch.randn(2, generator=ctx.rng.torch)
    noise = torch.randn(2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(latent + noise), "targets": synth.Tensor(noise)}
vector_dataset = synth.Spec("latent-importance-vectors", generator=latent_vectors, size=8, splits={"train": 1.0}, seed=5, root=root, monitor="none").run()
vector_train = vector_dataset.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
class LatentVectorPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=2, out_features=2)
    def forward(self, inputs):
        return self.network(inputs)
vector_trainer = Trainer(LatentVectorPredictor(), vector_train, recipe="regression", recipe_config={"loss": "latent-importance-reweighting", "loss_kwargs": {"importance_weights": [0.75, 0.25]}}, batch_size=4, max_epochs=1, device="cpu")
vector_trainer.fit()
@synth.generator
def latent_graphs(ctx):
    inputs = torch.randn(12, generator=ctx.rng.torch)
    targets = torch.randn(3, 4, generator=ctx.rng.torch)
    mask = torch.arange(3) < (int(ctx.index) % 3 + 1)
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets), "mask": synth.Tensor(mask)}
dataset = synth.Spec("latent-importance-reweighting", generator=latent_graphs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class LatentPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=12, out_features=12)
    def forward(self, inputs):
        return {"prediction": self.network(inputs).reshape(-1, 3, 4)}
trainer = Trainer(LatentPredictor(), train, recipe="structured-objective", recipe_config={"loss": "latent-importance-reweighting", "loss_kwargs": {"importance_weights": [0.5, 0.25, 0.125, 0.125]}, "bindings": {"logits_or_prediction": {"output": "prediction"}, "targets": {"batch": "targets"}, "mask": {"batch": "mask"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
